<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
use Sentinel\Repositories\PermissionRepository;
final class SubcontractorService
{
 use DeliveryOperations;
 public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly PermissionRepository $permissions) {}
 public function list():array {$rows=$this->db->fetchAll('SELECT * FROM subcontractor_companies WHERE company_id=:company ORDER BY subcontractor_id DESC LIMIT 300',['company'=>$this->company()]);foreach($rows as&$r){$p=['company'=>$this->company(),'id'=>$r['subcontractor_id']];$r['sites']=$this->db->fetchAll('SELECT * FROM subcontractor_sites WHERE company_id=:company AND subcontractor_id=:id',$p);$r['users']=$this->db->fetchAll('SELECT user_id,linked_at FROM subcontractor_users WHERE company_id=:company AND subcontractor_id=:id',$p);$r['history']=$this->events('subcontractor',$r['subcontractor_id']);}return $rows;}
 public function save(?string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['expected_revision','company_name','registration_reference','contact_details','licence_reference','licence_expires_on','insurance_reference','insurance_expires_on','state']);$state=$in['state']??null;if(!in_array($state,['ACTIVE','SUSPENDED'],true))throw HttpException::unprocessable('Choose active or suspended.');$v=['company'=>$this->company(),'name'=>$this->text($in['company_name']??null,150),'registration'=>$this->text($in['registration_reference']??null,150),'contact'=>$this->text($in['contact_details']??null,1000),'licence'=>$this->text($in['licence_reference']??null,300),'licence_date'=>$this->day($in['licence_expires_on']??null),'insurance'=>$this->text($in['insurance_reference']??null,300),'insurance_date'=>$this->day($in['insurance_expires_on']??null),'state'=>$state];if($this->db->fetch('SELECT subcontractor_id FROM subcontractor_companies WHERE company_id=:company AND registration_reference=:ref AND subcontractor_id<>:id',['company'=>$this->company(),'ref'=>$v['registration'],'id'=>$id??0]))throw HttpException::conflict('Registration already recorded.');if($id){$r=$this->row('subcontractor_companies','subcontractor_id',$id);$this->revision($r,$in);$this->db->execute('UPDATE subcontractor_companies SET company_name=:name,registration_reference=:registration,contact_details=:contact,licence_reference=:licence,licence_expires_on=:licence_date,insurance_reference=:insurance,insurance_expires_on=:insurance_date,state=:state,revision=revision+1 WHERE company_id=:company AND subcontractor_id=:id',$v+['id'=>$id]);}else{$this->db->execute('INSERT INTO subcontractor_companies(company_id,company_name,registration_reference,contact_details,licence_reference,licence_expires_on,insurance_reference,insurance_expires_on,state) VALUES(:company,:name,:registration,:contact,:licence,:licence_date,:insurance,:insurance_date,:state)',$v);$id=(string)$this->db->connection()->lastInsertId();}$this->history('subcontractor',$id,'SAVED','Document references recorded; approved sites must be reviewed after each company revision.');return ['id'=>$id];});}
 public function approveSite(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['site_id','valid_until','expected_revision']);$r=$this->row('subcontractor_companies','subcontractor_id',$id);$this->revision($r,$in);$s=$this->site($in['site_id']??null);$until=$this->day($in['valid_until']??null);if($r['state']!=='ACTIVE'||$until<gmdate('Y-m-d')||$until>$r['licence_expires_on']||$until>$r['insurance_expires_on'])throw HttpException::unprocessable('Site approval must be active and expire no later than both documents.');$p=['company'=>$this->company(),'id'=>$id,'site'=>$s['site_id']];$this->db->execute('DELETE FROM subcontractor_sites WHERE company_id=:company AND subcontractor_id=:id AND site_id=:site',$p);$this->db->execute('INSERT INTO subcontractor_sites(company_id,subcontractor_id,site_id,valid_until,approved_revision,approved_by_user_id,approved_at) VALUES(:company,:id,:site,:until,:revision,:actor,:now)',$p+['until'=>$until,'revision'=>$r['revision'],'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$this->history('subcontractor',$id,'SITE_APPROVED','Site #'.$s['site_id'].' until '.$until);return ['approved'=>true];});}
 public function revokeSite(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['site_id','notes']);$this->row('subcontractor_companies','subcontractor_id',$id);$site=$this->site($in['site_id']??null);$notes=$this->text($in['notes']??null,1000);$this->db->execute('DELETE FROM subcontractor_sites WHERE company_id=:company AND subcontractor_id=:id AND site_id=:site',['company'=>$this->company(),'id'=>$id,'site'=>$site['site_id']]);$this->history('subcontractor',$id,'SITE_REVOKED','Site #'.$site['site_id'].': '.$notes);return ['revoked'=>true];});}
 public function member(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['user_id','enabled']);$this->row('subcontractor_companies','subcontractor_id',$id);$u=$this->row('users','user_id',$in['user_id']??null);if(!is_bool($in['enabled']??null)||(string)$u['user_id']===$this->actor())throw HttpException::unprocessable('Choose a different individual account and explicit enabled flag.');if(!$in['enabled']){if(!$this->db->fetch('SELECT membership_id FROM subcontractor_users WHERE company_id=:company AND subcontractor_id=:id AND user_id=:user',['company'=>$this->company(),'id'=>$id,'user'=>$u['user_id']]))throw HttpException::notFound();// Removing a contractor link must not grant normal employee access.
 $this->db->execute("UPDATE users SET status='INACTIVE' WHERE company_id=:company AND user_id=:user",['company'=>$this->company(),'user'=>$u['user_id']]);$this->history('subcontractor',$id,'USER_DISABLED','User #'.$u['user_id']);return ['disabled'=>true];}
 if($u['status']!=='ACTIVE'||!$this->permissions->userHasPermission((string)$u['user_id'],'site_scope.restricted'))throw HttpException::unprocessable('First assign an active, restricted site-only account.');$old=$this->db->fetch('SELECT subcontractor_id FROM subcontractor_users WHERE company_id=:company AND user_id=:user',['company'=>$this->company(),'user'=>$u['user_id']]);if($old&&(string)$old['subcontractor_id']!==$id)throw HttpException::conflict('Account already belongs to another subcontractor.');if(!$old)$this->db->execute('INSERT INTO subcontractor_users(company_id,subcontractor_id,user_id,linked_by_user_id,linked_at) VALUES(:company,:id,:user,:actor,:now)',['company'=>$this->company(),'id'=>$id,'user'=>$u['user_id'],'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$this->db->execute('UPDATE integration_credentials SET revoked_at=:now WHERE company_id=:company AND created_by_user_id=:user AND revoked_at IS NULL',['now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'user'=>$u['user_id']]);$this->history('subcontractor',$id,'USER_LINKED','User #'.$u['user_id'].'; explicit user site grants are still required.');return ['linked'=>true];});}
}
